  'Choose field by field what\'s public, what\'s private, what\'s visible only to people with the link. You decide who sees what.': 'Sie entscheiden Feld für Feld, was öffentlich, privat oder nur über einen Link sichtbar ist. Sie bestimmen, wer was sieht.',
  'Choose the right door for you: the business ecosystem, or the talent platform.': 'Wählen Sie den richtigen Einstieg: das Business-Ökosystem oder die Talentplattform.',
  'Clear request routing': 'Klare Anfrage-Zuordnung',
