  'Companies': 'Unternehmen',
  'Companies grow together. Talents unleash potential. Capital has a lasting impact.': 'Unternehmen wachsen gemeinsam. Talente entfalten Potenzial. Kapital wirkt nachhaltig.',
  'Companies hire on Identity experience, not CV keywords. The matches are real.': 'Unternehmen stellen nach Identity-Erfahrung ein, nicht nach CV-Schlagwörtern. Die Matches sind echt.',
