  'Discover the Identity&rarr;': 'Identity entdecken →',
  'Discover how to integrate the Business Units into your growth strategy. Enter through one module, benefit from all.': 'Entdecken Sie, wie Sie die Business Units in Ihre Wachstumsstrategie integrieren. Über ein Modul einsteigen, von allen profitieren.',
  'Discover our projects for a climate-friendly economy.': 'Entdecken Sie unsere Projekte für eine klimafreundliche Wirtschaft.',
  'Discover the award': 'Auszeichnung entdecken',
  'Discover the foundation': 'Stiftung entdecken',
  'Discover the model that suits you best and start your journey.': 'Entdecken Sie das Modell, das am besten zu Ihnen passt, und starten Sie Ihre Reise.',
  'Each unit has its own focus, but they are designed to work together as one coordinated growth system.': 'Jede Unit hat ihren eigenen Fokus, ist aber darauf ausgelegt, als koordiniertes Wachstumssystem zusammenzuarbeiten.',
  'Economic crises': 'Wirtschaftskrisen',
  'Economic growth built on synergy, not internal competition.': 'Wirtschaftliches Wachstum auf Basis von Synergie, nicht interner Konkurrenz.',
  'Economic sustainability for us means creating systems that remain stable even in times of uncertainty and global change. Companies should not only grow but continuously evolve and become resilient to change.': 'Wirtschaftliche Nachhaltigkeit bedeutet für uns, Systeme zu schaffen, die auch in Zeiten von Unsicherheit und globalem Wandel stabil bleiben. Unternehmen sollen nicht nur wachsen, sondern sich kontinuierlich weiterentwickeln und resilient werden.',
  'Economy': 'Wirtschaft',
  'Ecosystem': 'Ökosystem',
  'Ecosystem synergies': 'Ökosystem-Synergien',
  'Educational institutions and talent-focused organizations.': 'Bildungseinrichtungen und talentorientierte Organisationen.',
  'Efficient and resource-saving buildings.': 'Effiziente und ressourcenschonende Gebäude.',
  'EI Generation': 'EI Generation',
  'EI.one Brand': 'EI.one Marke',
  'EI.ONE creates an environment where capital is used efficiently, growth is controlled and scaled, and risks are structurally reduced.': 'EI.ONE schafft ein Umfeld, in dem Kapital effizient eingesetzt, Wachstum kontrolliert skaliert und Risiken strukturell reduziert werden.',
  'ei.one holds four dimensions together. They are distinct but work as a single system.': 'ei.one hält vier Dimensionen zusammen. Sie sind eigenständig, funktionieren aber als ein System.',
  'EI.one is not a single company idea. It is a functioning scalable system built around education, experience, economy, and environment.': 'EI.one ist keine einzelne Unternehmensidee. Es ist ein funktionierendes, skalierbares System rund um Bildung, Erfahrung, Wirtschaft und Umwelt.',
  'EI.one is not just a project. It is much more.': 'EI.one ist nicht nur ein Projekt. Es ist viel mehr.',
  'EI.one is the home of the EI Generation.': 'EI.one ist das Zuhause der EI Generation.',
  'EI.one stands for a new generation of economic systems - intelligent, connected, and sustainable.': 'EI.one steht für eine neue Generation wirtschaftlicher Systeme - intelligent, vernetzt und nachhaltig.',
  'EI.one supports this development through a globally oriented network that brings together talents, ideas, and projects. Our goal is to promote an economy that is human, inclusive, and future-oriented.': 'EI.one unterstützt diese Entwicklung durch ein global ausgerichtetes Netzwerk, das Talente, Ideen und Projekte zusammenbringt. Unser Ziel ist es, eine menschliche, inklusive und zukunftsorientierte Wirtschaft zu fördern.',
  'EI.ONE thrives on complementary entrepreneurs.': 'EI.ONE lebt von komplementären Unternehmern.',
  'El.one pursues the vision of a future where economy, technology, and environment are in balance -- an intelligent ecosystem that enables sustainable solutions.': 'EI.one verfolgt die Vision einer Zukunft, in der Wirtschaft, Technologie und Umwelt im Gleichgewicht sind - ein intelligentes Ökosystem, das nachhaltige Lösungen ermöglicht.',
  'Email Password Reset Link': 'Link zum Zurücksetzen des Passworts senden',
  'Energy audits, building retrofits, optimisation of industrial consumption. Concrete pathways toward energy independence.': 'Energieaudits, Gebäudesanierungen und Optimierung industrieller Verbräuche. Konkrete Wege zur Energieunabhängigkeit.',
  'Energy transition and green solutions': 'Energiewende und grüne Lösungen',
  'Entrepreneurs': 'Unternehmer',
  'Entrepreneurship means growing together.': 'Unternehmertum bedeutet, gemeinsam zu wachsen.',
  'Environmental KPIs, transparent reporting and tracking of real impact. Sustainability is proven, not declared.': 'Umwelt-KPIs, transparentes Reporting und Nachverfolgung realer Wirkung. Nachhaltigkeit wird bewiesen, nicht behauptet.',
  'Environmental sustainability with measurable and traceable projects.': 'Ökologische Nachhaltigkeit mit messbaren und nachvollziehbaren Projekten.',
  'ESG at the heart of everything': 'ESG im Zentrum von allem',
  'Ethical growth': 'Ethisches Wachstum',
  'Every experience at an ecosystem company is attested by whoever had you do it and recorded on the blockchain as an immutable credential. Attachments, roles, results â€” all verifiable.': 'Jede Erfahrung in einem Unternehmen des Ökosystems wird von der Person bestätigt, die Ihnen die Aufgabe gegeben hat, und als unveränderbarer Nachweis auf der Blockchain gespeichert. Anhänge, Rollen, Ergebnisse — alles verifizierbar.',
  'Every experience is attested by whoever had you do it and anchored on the blockchain as a verifiable credential. Not words, cryptographic proof.': 'Jede Erfahrung wird von der Person bestätigt, die Ihnen die Aufgabe gegeben hat, und als verifizierbarer Nachweis auf der Blockchain verankert. Keine Worte, sondern kryptografischer Beweis.',
