  'Expi4D Technology': 'Expi4D Technologie',
  'Fast partnership review': 'Schnelle Partnerschaftsprüfung',
  'Fill out the form to speak with our Partnership team.': 'Füllen Sie das Formular aus, um mit unserem Partnership-Team zu sprechen.',
  'Focus on climate-friendly energy systems.': 'Fokus auf klimafreundliche Energiesysteme.',
  'For a smarter and more sustainable economy.': 'Für eine intelligentere und nachhaltigere Wirtschaft.',
  'For Businesses': 'Für Unternehmen',
  'For Investors': 'Für Investoren',
  'For us, ecological sustainability does not mean renunciation, but progress. It stands for innovation, responsibility, and the possibility of combining economic development with the protection of our planet.': 'Für uns bedeutet ökologische Nachhaltigkeit nicht Verzicht, sondern Fortschritt. Sie steht für Innovation, Verantwortung und die Möglichkeit, wirtschaftliche Entwicklung mit dem Schutz unseres Planeten zu verbinden.',
  'For us, economic sustainability means more than just financial success. It stands for stable, resilient, and long-term viable business models that promote innovation, use resources efficiently, and simultaneously make a positive contribution to society.': 'Für uns bedeutet wirtschaftliche Nachhaltigkeit mehr als finanziellen Erfolg. Sie steht für stabile, resiliente und langfristig tragfähige Geschäftsmodelle, die Innovation fördern, Ressourcen effizient nutzen und gleichzeitig einen positiven Beitrag zur Gesellschaft leisten.',
  'From energy production to reporting, each project area is designed to create measurable environmental and economic value.': 'Von Energieproduktion bis Reporting ist jeder Projektbereich darauf ausgelegt, messbaren ökologischen und wirtschaftlichen Wert zu schaffen.',
  'From selection to measurable impact.': 'Von der Auswahl bis zum messbaren Impact.',
  'Full EI.one brand': 'Vollständige EI.one Marke',
  'Full infrastructure': 'Vollständige Infrastruktur',
  'Functioning customer acquisition directly from the ecosystem itself.': 'Funktionierende Kundengewinnung direkt aus dem Ökosystem selbst.',
  'Get in touch. We\'ll assess together whether it fits our model and how we can support its execution.': 'Kontaktieren Sie uns. Gemeinsam prüfen wir, ob es zu unserem Modell passt und wie wir die Umsetzung unterstützen können.',
