  'Internships, project work and mentoring become a channel of verified talent, trusted partnerships and a qualified commercial network. Your experiences attract the best. The best grow your business.': 'Praktika, Projektarbeit und Mentoring werden zu einem Kanal für verifizierte Talente, vertrauensvolle Partnerschaften und ein qualifiziertes Geschäftsnetzwerk. Ihre Erfahrungen ziehen die Besten an. Die Besten lassen Ihr Unternehmen wachsen.',
  'Investors invest not only in visions, but in a robust and resilient system offering security and growth.': 'Investoren investieren nicht nur in Visionen, sondern in ein robustes und resilientes System, das Sicherheit und Wachstum bietet.',
