  'Photovoltaic plants, energy storage and wind solutions for businesses and properties. We turn energy from a cost factor into a source of independence.': 'Photovoltaikanlagen, Energiespeicher und Windlösungen für Unternehmen und Immobilien. Wir verwandeln Energie von einem Kostenfaktor in eine Quelle der Unabhängigkeit.',
