  'Social inequalities': 'Soziale Ungleichheiten',
  'Social sustainability for us also means promoting new forms of collaboration. In an increasingly connected world, innovation and progress no longer arise in isolation but through cooperation between people, companies, and organizations.': 'Soziale Nachhaltigkeit bedeutet für uns auch, neue Formen der Zusammenarbeit zu fördern. In einer zunehmend vernetzten Welt entstehen Innovation und Fortschritt nicht mehr isoliert, sondern durch Kooperation zwischen Menschen, Unternehmen und Organisationen.',
