  'Sponsors and partners build the training paths. You learn where the skills are really needed - not in the abstract.': 'Sponsoren und Partner bauen die Lernpfade. Sie lernen dort, wo die Fähigkeiten wirklich gebraucht werden - nicht abstrakt.',
