  'The benefits of being part of an integrated and high-performance ecosystem.': 'Die Vorteile, Teil eines integrierten und leistungsstarken Ökosystems zu sein.',
  'The best people come to companies that offer experience verifiable in the Identity.': 'Die besten Menschen kommen zu Unternehmen, die verifizierbare Erfahrung in der Identity bieten.',
  'the ecosystem companies attest the experience you\'ve built working with them': 'die Unternehmen des Ökosystems bestätigen die Erfahrung, die Sie durch die Arbeit mit ihnen aufgebaut haben',
  'The EI Generation was born to address the real-world challenges and turn them into sustainable opportunities.': 'Die EI Generation entstand, um reale Herausforderungen anzugehen und sie in nachhaltige Chancen zu verwandeln.',
  'The entrepreneur program is ideal for:': 'Das Unternehmerprogramm ist ideal für:',
  'The Experience Identity is different. Every experience you add is attested by whoever had you do it â€” a company in the ecosystem, an Academy partner, a real project. What people see is your actual work, not your self-promotion.': 'Die Experience Identity ist anders. Jede Erfahrung, die Sie hinzufügen, wird von der Person bestätigt, die Ihnen die Aufgabe gegeben hat — einem Unternehmen im Ökosystem, einem Academy-Partner oder einem echten Projekt. Sichtbar ist Ihre tatsächliche Arbeit, nicht Ihre Selbstdarstellung.',
  'The Franchise Partner is the official EI.one representative in a territory. They manage and develop the local ecosystem, coordinating modules, partners, and clients.': 'Der Franchise-Partner ist der offizielle EI.one Vertreter in einem Gebiet. Er verwaltet und entwickelt das lokale Ökosystem und koordiniert Module, Partner und Kunden.',
  'The Identity follows you from one role to the next. It grows with you, even if you change company.': 'Die Identity begleitet Sie von einer Rolle zur nächsten. Sie wächst mit Ihnen, auch wenn Sie das Unternehmen wechseln.',
  'The Identity isn\'t an isolated page. It\'s where the two doors of ei.one meet.': 'Die Identity ist keine isolierte Seite. Hier treffen die zwei Türen von ei.one aufeinander.',
  'The License Partner uses one or more EI.one modules within their own company. They remain independent but operate according to ecosystem standards.': 'Der Lizenz-Partner nutzt ein oder mehrere EI.one Module im eigenen Unternehmen. Er bleibt unabhängig, arbeitet aber nach Ökosystem-Standards.',
  'The White Label Partner uses EI.one technology, processes, and modules under their own brand. EI.one works "behind the scenes".': 'Der White-Label-Partner nutzt EI.one Technologie, Prozesse und Module unter eigener Marke. EI.one arbeitet im Hintergrund.',
  'The workplace becomes a learning engine for the people who work in it.': 'Der Arbeitsplatz wird zum Lernmotor für die Menschen, die dort arbeiten.',
  'They are independent, but the more you use them together, the more they deliver.': 'Sie sind unabhängig, aber je mehr Sie sie zusammen nutzen, desto mehr leisten sie.',
  'This-Priis - SVA Zürich': 'This-Priis - SVA Zürich',
  'Those looking for investments with real impact.': 'Menschen, die Investitionen mit echter Wirkung suchen.',
  'Three ways to participate in the EI.one ecosystem, from full local leadership to modular activation and brand-integrated infrastructure.': 'Drei Wege zur Teilnahme am EI.one Ökosystem: von lokaler Führung über modulare Aktivierung bis zu markenintegrierter Infrastruktur.',
  'Through projects in the fields of renewable energy and energy efficiency, we support companies in making their processes more environmentally friendly.': 'Durch Projekte in den Bereichen erneuerbare Energie und Energieeffizienz unterstützen wir Unternehmen dabei, ihre Prozesse umweltfreundlicher zu gestalten.',
  'Tools that move ideas into practical use.': 'Tools, die Ideen in die praktische Anwendung bringen.',
  'Uniting Business and Values': 'Wirtschaft und Werte vereinen',
