  'Visit Stiftung ToGo': 'Stiftung ToGo besuchen',
  'Visit SVA Zürich': 'SVA Zürich besuchen',
  'We analyse real opportunities, assess technical and economic feasibility and only select what delivers concrete impact.': 'Wir analysieren echte Chancen, prüfen technische und wirtschaftliche Machbarkeit und wählen nur aus, was konkrete Wirkung bringt.',
  'We are not spectators of change': 'Wir sind keine Zuschauer des Wandels',
  'We are not spectators of change.': 'Wir sind keine Zuschauer des Wandels.',
  'We are the architects of change.': 'Wir sind die Architekten des Wandels.',
  'We are the designers of change. EI.one is the home of the EI Generation.': 'Wir sind die Gestalter des Wandels. EI.one ist das Zuhause der EI Generation.',
  'We Are the EI Generation': 'Wir sind die EI Generation',
  'We believe businesses have a responsibility to contribute to a better world.': 'Wir glauben, dass Unternehmen Verantwortung tragen, zu einer besseren Welt beizutragen.',
  'We build the financial model, identify partners and investors, and define success indicators before we start.': 'Wir bauen das Finanzmodell, identifizieren Partner und Investoren und definieren Erfolgsindikatoren, bevor wir starten.',
  'We coordinate execution with network partners. Technical capabilities come from the ecosystem; the orchestration comes from EI.one.': 'Wir koordinieren die Umsetzung mit Netzwerkpartnern. Technische Fähigkeiten kommen aus dem Ökosystem; die Orchestrierung kommt von EI.one.',
  'We don\'t promise shortcuts. We build the future.': 'Wir versprechen keine Abkürzungen. Wir bauen die Zukunft.',
  'We follow no trends. We build structures that last.': 'Wir folgen keinen Trends. Wir bauen Strukturen, die Bestand haben.',
  'What EI.one is': 'Was EI.one ist',
  'What you did, attested by the people who saw you do it.': 'Was Sie getan haben, bestätigt von den Menschen, die es gesehen haben.',
