  'You are a co-builder of the system.': 'Sie sind Mitgestalter des Systems.',
  'You are not just a partner.': 'Sie sind nicht nur Partner.',
  'you build real experiences inside the ecosystem\'s companies while growing your own project.': 'Sie bauen echte Erfahrungen in Unternehmen des Ökosystems auf und entwickeln gleichzeitig Ihr eigenes Projekt.',
  'you crystallize years of work into a profile that proves itself and lets you be found.': 'Sie verdichten Jahre an Arbeit zu einem Profil, das sich selbst beweist und Sie auffindbar macht.',
  'You decide what\'s public, what\'s private and what\'s visible only via a shared link.': 'Sie entscheiden, was öffentlich, privat oder nur über einen geteilten Link sichtbar ist.',
  'you want to discover where you fit, without relying only on the first CV you send out.': 'Sie möchten entdecken, wo Sie hingehören, ohne sich nur auf den ersten Lebenslauf zu verlassen, den Sie versenden.',
  'Your Brand, Our Infrastructure': 'Ihre Marke, unsere Infrastruktur',
  'Your digital record of what actually did. Verified by the ecosystem\'s companies who saw you do it.': 'Ihr digitaler Nachweis dessen, was Sie tatsächlich getan haben. Verifiziert durch die Unternehmen des Ökosystems, die es gesehen haben.',
  'Your digital record of what you actually did. Verified by the ecosystem\'s companies who saw you do it.': 'Ihr digitaler Nachweis dessen, was Sie tatsächlich getan haben. Verifiziert durch die Unternehmen des Ökosystems, die es gesehen haben.',
  'Your digital register, verified by the companies of the ecosystem. Build it over time, share it when you need to.': 'Ihr digitales Register, verifiziert durch die Unternehmen des Ökosystems. Bauen Sie es mit der Zeit auf und teilen Sie es, wenn Sie es brauchen.',
