  'Experience, Education, Economy and Environment work as one.': 'Experience, Bildung, Wirtschaft und Umwelt arbeiten als Einheit.',
  'Each BU works in synergy with the others. That\'s how the ecosystem becomes more than the sum of its parts.': 'Jede BU arbeitet in Synergie mit den anderen. So wird das Ökosystem mehr als die Summe seiner Teile.',
  'It\'s the infrastructure that turns companies into hubs of learning, innovation and growth.': 'Es ist die Infrastruktur, die Unternehmen zu Zentren für Lernen, Innovation und Wachstum macht.',
