Object.assign(de, {
  'ei.one isn\'t built to teach people or just to connect them. It exists to transform companies into engines of learning, innovation and growth. Every company that joins the ecosystem creates new commercial relationships, attracts talent, develops skills, increases its visibility, and generates measurable ESG impact.': 'ei.one wurde nicht gebaut, um Menschen nur zu unterrichten oder sie einfach zu verbinden. Es existiert, um Unternehmen in Motoren fuer Lernen, Innovation und Wachstum zu verwandeln. Jedes Unternehmen, das dem Oekosystem beitritt, schafft neue Geschaeftsbeziehungen, zieht Talente an, entwickelt Kompetenzen, erhoeht seine Sichtbarkeit und erzeugt messbaren ESG-Impact.',
  'Learning': 'Lernen',
  'He gave life to the': 'Er hat die',
  'as a concrete response to the challenges of our time. EI.one is the result of this journey.': 'als konkrete Antwort auf die Herausforderungen unserer Zeit ins Leben gerufen. EI.one ist das Ergebnis dieser Reise.',
  'Entrepreneur and ecosystem builder. For over 15 years he\'s been developing projects that combine sustainability, technology, human network and ethical growth.': 'Unternehmer und Oekosystem-Builder. Seit ueber 15 Jahren entwickelt er Projekte, die Nachhaltigkeit, Technologie, menschliche Netzwerke und ethisches Wachstum verbinden.',
  'He gave life to the EI Generation as a concrete response to the challenges of our time. EI.one is the result of this journey.': 'Er hat die EI Generation als konkrete Antwort auf die Herausforderungen unserer Zeit ins Leben gerufen. EI.one ist das Ergebnis dieser Reise.',
  'Human network': 'Menschliches Netzwerk',
  'Ethical growth': 'Ethisches Wachstum',
  'The EI Generation consists of entrepreneurs, professionals, innovators, and talents who believe in a new development model.': 'Die EI Generation besteht aus Unternehmern, Fachleuten, Innovatoren und Talenten, die an ein neues Entwicklungsmodell glauben.',
  'We believe the future belongs to ecosystems that can unite business and values, technology and humanity, growth and responsibility, profit and positive impact.': 'Wir glauben, dass die Zukunft Oekosystemen gehoert, die Wirtschaft und Werte, Technologie und Menschlichkeit, Wachstum und Verantwortung sowie Gewinn und positiven Impact verbinden koennen.',
  'ei.one was born from the concrete entrepreneurial experience of the founder and partners in the sectors that today make up the ecosystem: renewable energy, business development, digital & marketing, IT & AI, real estate. We\'re not theory. We\'re practice and structure.': 'ei.one entstand aus der konkreten unternehmerischen Erfahrung des Gruenders und der Partner in den Bereichen, die heute das Oekosystem bilden: erneuerbare Energie, Geschaeftsentwicklung, Digital & Marketing, IT & KI und Immobilien. Wir sind keine Theorie. Wir sind Praxis und Struktur.',
  'Energy transition and green solutions': 'Energiewende und gruene Loesungen',
  'Three-time nominees at the This-Priis - the award founded by Matthias Widmer of SVA Zürich in 2006 to recognize companies that promote inclusion and professional integration of people with limitations.': 'Dreimal nominiert fuer den This-Priis - die Auszeichnung, die Matthias Widmer von SVA Zuerich 2006 gegruendet hat, um Unternehmen zu wuerdigen, die Inklusion und berufliche Integration von Menschen mit Einschraenkungen foerdern.',
  'For us it\'s not a trophy; it\'s confirmation that the way we build teams works, and it scales to the entire ecosystem.': 'Fuer uns ist es keine Trophaee; es ist die Bestaetigung, dass die Art, wie wir Teams aufbauen, funktioniert und auf das gesamte Oekosystem skalierbar ist.',
  'We support the Swiss foundation Stiftung ToGo, which organizes free cataract operations in Togo. To date, the foundation has helped over 1,000 people recover their sight.': 'Wir unterstuetzen die Schweizer Stiftung ToGo, die kostenlose Kataraktoperationen in Togo organisiert. Bis heute hat die Stiftung ueber 1.000 Menschen geholfen, ihr Augenlicht wiederzuerlangen.',
  'It\'s a concrete example of what we mean by "real value": a measurable, verifiable action that changes individual lives.': 'Es ist ein konkretes Beispiel dafuer, was wir mit echtem Wert meinen: eine messbare, nachweisbare Handlung, die individuelle Leben veraendert.',
  'Our commitments': 'Unser Engagement',
  'We believe in an ecosystem that grows together with its community. These are the companies, institutions and organizations we work with, that recognize and support our work.': 'Wir glauben an ein Oekosystem, das gemeinsam mit seiner Community waechst. Das sind die Unternehmen, Institutionen und Organisationen, mit denen wir arbeiten und die unsere Arbeit anerkennen und unterstuetzen.',
  'Shared growth': 'Gemeinsames Wachstum',
  'Companies': 'Unternehmen',
  'Our Partners': 'Unsere Partner',
  'Companies, institutions and organizations that recognize and support our work.': 'Unternehmen, Institutionen und Organisationen, die unsere Arbeit anerkennen und unterstuetzen.',
  'Institutions': 'Institutionen',
  'Organizations': 'Organisationen',
  'Ecology meets innovation': 'Oekologie trifft Innovation',
  'Protecting Our Environment': 'Unsere Umwelt schuetzen',
  'Protecting our environment is one of the central challenges of the 21st century. For us, ecological sustainability means using natural resources responsibly, using energy efficiently, and developing technologies that reduce the ecological footprint of our economy.': 'Der Schutz unserer Umwelt ist eine der zentralen Herausforderungen des 21. Jahrhunderts. Fuer uns bedeutet oekologische Nachhaltigkeit, natuerliche Ressourcen verantwortungsvoll zu nutzen, Energie effizient einzusetzen und Technologien zu entwickeln, die den oekologischen Fussabdruck unserer Wirtschaft reduzieren.',
  'At EI.one, we combine technological innovation with ecological awareness. Our approach is based on the conviction that sustainable solutions are not only necessary but also offer enormous opportunities for the economy, society, and innovation.': 'Bei EI.one verbinden wir technologische Innovation mit oekologischem Bewusstsein. Unser Ansatz basiert auf der Ueberzeugung, dass nachhaltige Loesungen nicht nur notwendig sind, sondern auch grosse Chancen fuer Wirtschaft, Gesellschaft und Innovation bieten.',
  'Responsible resources': 'Verantwortungsvolle Ressourcen',
  'Efficient energy': 'Effiziente Energie',
  'Reduced footprint': 'Reduzierter Fussabdruck',
  'Concrete initiatives with measurable impact. We turn ecological sustainability into real projects, with clear indicators and transparent results.': 'Konkrete Initiativen mit messbarem Impact. Wir verwandeln oekologische Nachhaltigkeit in reale Projekte, mit klaren Indikatoren und transparenten Ergebnissen.',
  'Operational initiatives, not abstract promises': 'Operative Initiativen, keine abstrakten Versprechen',
  'Progress you can measure and compare': 'Fortschritt, den Sie messen und vergleichen koennen',
  'Impact made visible for every stakeholder': 'Impact sichtbar fuer alle Stakeholder',
  'At EI.one, environmental sustainability isn\'t a slogan. It\'s an operational line with selection criteria, execution phases and impact metrics.': 'Bei EI.one ist oekologische Nachhaltigkeit kein Slogan. Sie ist eine operative Linie mit Auswahlkriterien, Umsetzungsphasen und Impact-Metriken.',
  'We work with companies in our network, industrial partners and investors who share one priority: generating economic value without compromising ecological value.': 'Wir arbeiten mit Unternehmen in unserem Netzwerk, Industriepartnern und Investoren, die eine Prioritaet teilen: wirtschaftlichen Wert schaffen, ohne oekologischen Wert zu gefaehrden.',
  'A selection of installations delivered across Switzerland in collaboration with': 'Eine Auswahl von Anlagen, die in der Schweiz in Zusammenarbeit mit',
  'a partner in our ecosystem.': 'einem Partner in unserem Oekosystem, umgesetzt wurden.',
  'Multi-family building': 'Mehrfamilienhaus',
  'Private home': 'Privathaus',
  'Single-family home': 'Einfamilienhaus',
  'See all references on Techede.ch': 'Alle Referenzen auf Techede.ch ansehen',
  'For every project we publish impact indicators: tons of CO2 avoided, kWh produced from renewable sources, percentage reduction in consumption. No stories - verifiable numbers.': 'Fuer jedes Projekt veroeffentlichen wir Impact-Indikatoren: vermiedene Tonnen CO2, kWh aus erneuerbaren Quellen und prozentuale Verbrauchsreduktion. Keine Geschichten - nachpruefbare Zahlen.',
  'For every project we publish impact indicators: tons of CO2 avoided, kWh produced from renewable sources, percentage reduction in consumption.': 'Fuer jedes Projekt veroeffentlichen wir Impact-Indikatoren: vermiedene Tonnen CO2, kWh aus erneuerbaren Quellen und prozentuale Verbrauchsreduktion.',
  'No stories - verifiable numbers.': 'Keine Geschichten - nachpruefbare Zahlen.',
  'Numbers that make sustainability visible.': 'Zahlen, die Nachhaltigkeit sichtbar machen.',
  'CO2 avoided': 'CO2 vermieden',
  'kWh produced': 'kWh produziert',
  'Consumption reduced': 'Verbrauch reduziert',
  'Build together': 'Gemeinsam aufbauen',
  'Cooperation': 'Zusammenarbeit',
  'Connections': 'Verbindungen',
  'Growth': 'Wachstum',
  'Integrated growth': 'Integriertes Wachstum',
  'Clients, projects, talents and visibility move through one connected ecosystem.': 'Kunden, Projekte, Talente und Sichtbarkeit bewegen sich durch ein verbundenes Oekosystem.',
  'Cooperation model': 'Kooperationsmodell',
  'In a saturated market, partnership is the key to differentiation. We offer not just a platform, but an environment of trust where businesses support each other.': 'In einem gesaettigten Markt ist Partnerschaft der Schluessel zur Differenzierung. Wir bieten nicht nur eine Plattform, sondern ein Umfeld des Vertrauens, in dem Unternehmen einander unterstuetzen.',
  'Fast partnership review': 'Schnelle Partnerschaftspruefung',
  'Clear request routing': 'Klare Weiterleitung der Anfrage',
  'Direct EI.ONE contact': 'Direkter EI.ONE Kontakt',
  'Company Name / Contact': 'Firmenname / Kontakt',
  'Business Email': 'Geschaeftliche E-Mail',
  'Request Type': 'Anfragetyp',
  'Entrepreneur Request': 'Unternehmer-Anfrage',
  'General Information': 'Allgemeine Informationen',
  'Collaboration Proposal': 'Kooperationsvorschlag',
  'Tell us about your company': 'Erzaehlen Sie uns von Ihrem Unternehmen',
  'ei.one - The ecosystem where people build real experience and become entrepreneurs.': 'ei.one - Das Oekosystem, in dem Menschen echte Erfahrung aufbauen und Unternehmer werden.',
  'The ecosystem\'s Business Units work together to transform companies into engines of learning, innovation and growth. Enter through one module, activate new commercial relationships, attract talent, develop skills, and amplify your visibility.': 'Die Business Units des Oekosystems arbeiten zusammen, um Unternehmen in Motoren fuer Lernen, Innovation und Wachstum zu verwandeln. Steigen Sie ueber ein Modul ein, aktivieren Sie neue Geschaeftsbeziehungen, gewinnen Sie Talente, entwickeln Sie Kompetenzen und verstaerken Sie Ihre Sichtbarkeit.',
  'Sales': 'Vertrieb',
  'Impact': 'Impact',
  'Enter through one module. Activate the whole ecosystem.': 'Ueber ein Modul einsteigen. Das ganze Oekosystem aktivieren.',
  'Business Units cover the strategic areas of a modern enterprise, connected so every module can support the others.': 'Business Units decken die strategischen Bereiche eines modernen Unternehmens ab und sind so verbunden, dass jedes Modul die anderen unterstuetzen kann.',
  'At ei.one, Business Units aren\'t "isolated providers". They\'re part of a single integrated and coordinated system. That\'s what makes the ecosystem really work.': 'Bei ei.one sind Business Units keine isolierten Anbieter. Sie sind Teil eines einzigen integrierten und koordinierten Systems. Genau das macht das Oekosystem wirklich wirksam.',
  'The EI.one Marketplace offers access to exclusive products and technologies born from our ecosystem. Our goal is to provide businesses with tools that make their visions tangible and real.': 'Der EI.one Marketplace bietet Zugang zu exklusiven Produkten und Technologien, die aus unserem Oekosystem entstehen. Unser Ziel ist es, Unternehmen Werkzeuge zu geben, die ihre Visionen greifbar und real machen.',
  'Exclusive products': 'Exklusive Produkte',
  'Applied technology': 'Angewandte Technologie',
  'Solutions developed inside the ecosystem.': 'Loesungen, die im Oekosystem entwickelt wurden.',
  'Tools that move ideas into practical use.': 'Tools, die Ideen in die praktische Anwendung bringen.',
  'Tangible visions': 'Greifbare Visionen',
  'Business concepts made visible, useful and real.': 'Geschaeftskonzepte sichtbar, nuetzlich und real machen.',
  'Why our Marketplace?': 'Warum unser Marketplace?',
  'Technology meets usability.': 'Technologie trifft Nutzbarkeit.',
  'Marketplace tools are selected for one reason: they have to become useful quickly, keep quality high, and create measurable business value.': 'Marketplace-Tools werden aus einem Grund ausgewaehlt: Sie muessen schnell nutzbar werden, hohe Qualitaet sichern und messbaren Geschaeftswert schaffen.',
  'Fast Integration': 'Schnelle Integration',
  'Guaranteed Quality': 'Garantierte Qualitaet',
  'Focus on ROI': 'Fokus auf ROI',
  'Only the best products from our ecosystem.': 'Nur die besten Produkte aus unserem Oekosystem.',
  'Want to activate the ecosystem for your business?': 'Moechten Sie das Oekosystem fuer Ihr Unternehmen aktivieren?',
  'Are you an investor?': 'Sind Sie Investor?',
  'Energy & Sustainability': 'Energie & Nachhaltigkeit',
  'Sales & Business Development': 'Vertrieb & Geschaeftsentwicklung',
  'Integrated Energy Systems': 'Integrierte Energiesysteme',
  '3D Visualization & Virtual Events': '3D-Visualisierung & virtuelle Events',
  'Digital & Brand Growth': 'Digitales & Markenwachstum',
  'IT, AI & Academy Systems': 'IT, KI & Academy-Systeme',
  'Professional Hygiene & Cleaning': 'Professionelle Hygiene & Reinigung',
  'Referral Marketing & Business Network': 'Empfehlungsmarketing & Business-Netzwerk',
  'Real Estate & Infrastructure': 'Immobilien & Infrastruktur',
  'Techede is the module dedicated to renewable energy and green solutions. We develop photovoltaic projects, energy storage systems, and consulting for energy transition. Our goal is to make clean energy accessible and profitable for businesses and individuals, supporting decarbonization and energy independence.': 'Techede ist das Modul fuer erneuerbare Energie und gruene Loesungen. Wir entwickeln Photovoltaikprojekte, Energiespeichersysteme und Beratung fuer die Energiewende. Unser Ziel ist es, saubere Energie fuer Unternehmen und Privatpersonen zugaenglich und wirtschaftlich zu machen und Dekarbonisierung sowie Energieunabhaengigkeit zu foerdern.',
  'SalesMaster is the module specialized in strategic sales and business development. We offer commercial training, sales team coaching, customized CRM systems, and customer acquisition strategies. We transform relationships into sustainable growth through proven methodologies focused on concrete results.': 'SalesMaster ist das Modul fuer strategischen Vertrieb und Geschaeftsentwicklung. Wir bieten Vertriebstrainings, Coaching fuer Sales-Teams, massgeschneiderte CRM-Systeme und Strategien zur Kundengewinnung. Mit bewaehrten Methoden und Fokus auf konkrete Ergebnisse verwandeln wir Beziehungen in nachhaltiges Wachstum.',
  'EQUICOÂ² is the module dedicated to integrated energy systems for businesses and properties. From feasibility analysis to the design and implementation of solar, wind and energy storage installations, we transform energy from a cost factor into a revenue source. We support high-energy-consuming companies towards full sustainable energy independence.': 'EQUICO2 ist das Modul fuer integrierte Energiesysteme fuer Unternehmen und Immobilien. Von der Machbarkeitsanalyse bis zur Planung und Umsetzung von Solar-, Wind- und Speicheranlagen verwandeln wir Energie vom Kostenfaktor in eine Einnahmequelle. Wir begleiten energieintensive Unternehmen auf dem Weg zu nachhaltiger Energieunabhaengigkeit.',
  'Archit.ooo is the module for 3D visualization and virtual events. We use Expi4D technology to create digital twins, immersive tours, virtual showrooms, and online exhibition spaces. We design the future by making every space accessible and interactive, revolutionizing how projects and properties are presented.': 'Archit.ooo ist das Modul fuer 3D-Visualisierung und virtuelle Events. Mit Expi4D-Technologie erstellen wir digitale Zwillinge, immersive Rundgaenge, virtuelle Showrooms und Online-Ausstellungsraeume. Wir gestalten die Zukunft, indem wir jeden Raum zugaenglich und interaktiv machen und die Praesentation von Projekten und Immobilien revolutionieren.',
  'MarketingMaster is the module for digital growth and brand positioning. We develop integrated marketing strategies, social media management, valuable content, advertising campaigns, and SEO. We build visibility with real value, transforming your online presence into concrete and measurable business opportunities.': 'MarketingMaster ist das Modul fuer digitales Wachstum und Markenpositionierung. Wir entwickeln integrierte Marketingstrategien, Social-Media-Management, wertvolle Inhalte, Werbekampagnen und SEO. Wir schaffen Sichtbarkeit mit echtem Wert und verwandeln Ihre Online-Praesenz in konkrete und messbare Geschaeftschancen.',
  'Netmaster is the technological heart of the EI.one ecosystem. We offer software development, AI solutions, cloud infrastructure, cybersecurity, and digital training through our Academy. The technological backbone that coordinates all modules, manages data, and trains the professionals of the EI Generation.': 'Netmaster ist das technologische Herz des EI.one Oekosystems. Wir bieten Softwareentwicklung, KI-Loesungen, Cloud-Infrastruktur, Cybersicherheit und digitale Weiterbildung ueber unsere Academy. Es ist das technologische Rueckgrat, das alle Module koordiniert, Daten verwaltet und die Fachkraefte der EI Generation ausbildet.',
  'Cleanlife is the module specialized in professional hygiene and cleaning solutions for businesses and facilities. With over 20 years of experience in the Swiss market, we offer industrial cleaning chemicals, professional machinery, maintenance services and tailored technical consulting for hotels, offices, restaurants and healthcare facilities.': 'Cleanlife ist das Modul fuer professionelle Hygiene- und Reinigungsloesungen fuer Unternehmen und Einrichtungen. Mit ueber 20 Jahren Erfahrung im Schweizer Markt bieten wir industrielle Reinigungschemie, professionelle Maschinen, Wartungsservices und massgeschneiderte technische Beratung fuer Hotels, Bueros, Restaurants und Gesundheitseinrichtungen.',
  'BNI focuses primarily on economic sustainability through systematic referral marketing that generates measurable growth and revenue. Social sustainability shows in values like \'Givers Gain\', long-term relationships and personal development.': 'BNI fokussiert vor allem auf wirtschaftliche Nachhaltigkeit durch systematisches Empfehlungsmarketing, das messbares Wachstum und Umsatz schafft. Soziale Nachhaltigkeit zeigt sich in Werten wie Givers Gain, langfristigen Beziehungen und persoenlicher Entwicklung.',
  'PropertyMaster is the module dedicated to sustainable real estate and infrastructure. We offer real estate consulting, valuations, asset management, project development, and energy requalification of buildings. Future-oriented real estate: we integrate sustainability, technology, and long-term value.': 'PropertyMaster ist das Modul fuer nachhaltige Immobilien und Infrastruktur. Wir bieten Immobilienberatung, Bewertungen, Asset Management, Projektentwicklung und energetische Requalifizierung von Gebaeuden. Zukunftsorientierte Immobilien: Wir verbinden Nachhaltigkeit, Technologie und langfristigen Wert.',
  'Archit.ooo is the innovative platform for 3D visualization and virtual events. We use the groundbreaking': 'Archit.ooo ist die innovative Plattform fuer 3D-Visualisierung und virtuelle Events. Wir nutzen die bahnbrechende',
  'technology to transform real spaces into experiential digital worlds.': 'Technologie, um reale Raeume in erlebbare digitale Welten zu verwandeln.',
  'Whether digital twins, immersive tours, virtual showrooms, or online exhibition spaces - Archit.ooo makes spaces accessible and interactive worldwide. We revolutionize the way projects and real estate are presented and experienced.': 'Ob digitale Zwillinge, immersive Rundgaenge, virtuelle Showrooms oder Online-Ausstellungsraeume - Archit.ooo macht Raeume weltweit zugaenglich und interaktiv. Wir revolutionieren die Art, wie Projekte und Immobilien praesentiert und erlebt werden.',
  'Maximum immersion': 'Maximale Immersion',
  'Precise copies of real spaces': 'Praezise Kopien realer Raeume',
  'Present your products anywhere': 'Praesentieren Sie Ihre Produkte ueberall',
  'Visit website': 'Website besuchen',
})

