  "As the EI Generation, we commit every day to a better future.": "Come EI Generation, ci impegniamo ogni giorno per un futuro migliore.",
  "At EI.one - Ecosystem Intelligence, we develop an intelligent ecosystem that connects companies, technologies, talents, and investors. Our goal is to support organizations in creating sustainable value, opening new markets, and strengthening their competitiveness in the long term.": "In EI.one - Ecosystem Intelligence sviluppiamo un ecosistema intelligente che connette aziende, tecnologie, talenti e investitori. Il nostro obiettivo e sostenere le organizzazioni nella creazione di valore sostenibile, nell'apertura di nuovi mercati e nel rafforzamento della competitivita a lungo termine.",
  "At EI.one, we believe in concrete values that guide every partnership. We are not looking for simple affiliates. We are looking for ecosystem leaders.": "In EI.one crediamo in valori concreti che guidano ogni partnership. Non cerchiamo semplici affiliati: cerchiamo leader di ecosistema.",
  "At EI.one, we believe that sustainable innovation can only emerge when people have access to knowledge, education, and new opportunities. That is why we promote a corporate culture based on collaboration, trust, diversity, and personal development.": "In EI.one crediamo che l'innovazione sostenibile possa nascere solo quando le persone hanno accesso a conoscenza, formazione e nuove opportunita. Per questo promuoviamo una cultura aziendale basata su collaborazione, fiducia, diversita e sviluppo personale.",
  "At EI.one, we combine technological innovation with ecological awareness. Our approach is based on the conviction that sustainable solutions are not only necessary but also offer enormous opportunities for the economy, society, and innovation.": "In EI.one uniamo innovazione tecnologica e consapevolezza ecologica. Il nostro approccio si basa sulla convinzione che le soluzioni sostenibili siano necessarie e offrano grandi opportunita per economia, societa e innovazione.",
