  "Economic sustainability for us means creating systems that remain stable even in times of uncertainty and global change. Companies should not only grow but continuously evolve and become resilient to change.": "Per noi sostenibilita economica significa creare sistemi che restano stabili anche in tempi di incertezza e cambiamento globale. Le aziende non devono solo crescere, ma evolvere continuamente e diventare resilienti al cambiamento.",
