  "EI.one stands for a new generation of economic systems - intelligent, connected, and sustainable.": "EI.one rappresenta una nuova generazione di sistemi economici: intelligenti, connessi e sostenibili.",
  "EI.one supports this development through a globally oriented network that brings together talents, ideas, and projects. Our goal is to promote an economy that is human, inclusive, and future-oriented.": "EI.one sostiene questo sviluppo attraverso una rete globale che unisce talenti, idee e progetti. Il nostro obiettivo e promuovere un'economia umana, inclusiva e orientata al futuro.",
  "EI.ONE thrives on complementary entrepreneurs.": "EI.ONE cresce grazie a imprenditori complementari.",
  "El.one pursues the vision of a future where economy, technology, and environment are in balance -- an intelligent ecosystem that enables sustainable solutions.": "EI.one persegue la visione di un futuro in cui economia, tecnologia e ambiente sono in equilibrio: un ecosistema intelligente che abilita soluzioni sostenibili.",
  "Energy audits, building retrofits, optimisation of industrial consumption. Concrete pathways toward energy independence.": "Audit energetici, riqualificazione degli edifici e ottimizzazione dei consumi industriali. Percorsi concreti verso l'indipendenza energetica.",
