  "Environmental KPIs, transparent reporting and tracking of real impact. Sustainability is proven, not declared.": "KPI ambientali, reporting trasparente e monitoraggio dell'impatto reale. La sostenibilita si dimostra, non si dichiara.",
  "Environmental sustainability with measurable and traceable projects.": "Sostenibilita ambientale con progetti misurabili e tracciabili.",
