  "For Investors": "Per investitori",
  "For us, ecological sustainability does not mean renunciation, but progress. It stands for innovation, responsibility, and the possibility of combining economic development with the protection of our planet.": "Per noi sostenibilita ecologica non significa rinuncia, ma progresso. Significa innovazione, responsabilita e possibilita di unire sviluppo economico e protezione del pianeta.",
  "For us, economic sustainability means more than just financial success. It stands for stable, resilient, and long-term viable business models that promote innovation, use resources efficiently, and simultaneously make a positive contribution to society.": "Per noi sostenibilita economica significa piu del successo finanziario. Significa modelli di business stabili, resilienti e sostenibili nel lungo periodo, che promuovono innovazione, usano le risorse in modo efficiente e contribuiscono positivamente alla societa.",
  "From energy production to reporting, each project area is designed to create measurable environmental and economic value.": "Dalla produzione energetica al reporting, ogni area di progetto e pensata per creare valore ambientale ed economico misurabile.",
  "From selection to measurable impact.": "Dalla selezione all'impatto misurabile.",
  "Full EI.one brand": "Brand EI.one completo",
  "Full infrastructure": "Infrastruttura completa",
  "Functioning customer acquisition directly from the ecosystem itself.": "Acquisizione clienti funzionante direttamente dall'ecosistema stesso.",
  "Get in touch. We'll assess together whether it fits our model and how we can support its execution.": "Contattaci. Valuteremo insieme se il progetto si adatta al nostro modello e come possiamo supportarne l'esecuzione.",
  "Global scalability": "Scalabilita globale",
  "Governance system": "Sistema di governance",
