  "Identified and developed talents increase productivity and company value.": "I talenti identificati e sviluppati aumentano produttivita e valore aziendale.",
  "Impact made visible for every stakeholder": "Impatto visibile per ogni stakeholder",
  "Industrial investors": "Investitori industriali",
