  "International scalability": "Scalabilita internazionale",
  "Internships, project work and mentoring become a channel of verified talent, trusted partnerships and a qualified commercial network. Your experiences attract the best. The best grow your business.": "Stage, project work e mentoring diventano un canale di talenti verificati, partnership affidabili e rete commerciale qualificata. Le tue esperienze attraggono i migliori. I migliori fanno crescere la tua azienda.",
  "Investors invest not only in visions, but in a robust and resilient system offering security and growth.": "Gli investitori non investono solo in visioni, ma in un sistema robusto e resiliente che offre sicurezza e crescita.",
