  "Organizations": "Organizzazioni",
  "Photovoltaic plants, energy storage and wind solutions for businesses and properties. We turn energy from a cost factor into a source of independence.": "Impianti fotovoltaici, accumulo energetico e soluzioni eoliche per aziende e immobili. Trasformiamo l'energia da costo a fonte di indipendenza.",
  "Photovoltaic work delivered in Switzerland.": "Lavori fotovoltaici realizzati in Svizzera.",
