  "Progress you can measure and compare": "Progresso che puoi misurare e confrontare",
  "Projects that turn waste into resources. Reducing waste, reusing materials, building sustainable industrial processes.": "Progetti che trasformano i rifiuti in risorse. Riduzione degli sprechi, riuso dei materiali e processi industriali sostenibili.",
  "Protecting our environment is one of the central challenges of the 21st century. For us, ecological sustainability means using natural resources responsibly, using energy efficiently, and developing technologies that reduce the ecological footprint of our economy.": "Proteggere il nostro ambiente e una delle sfide centrali del XXI secolo. Per noi sostenibilita ecologica significa usare responsabilmente le risorse naturali, impiegare l'energia in modo efficiente e sviluppare tecnologie che riducano l'impronta ecologica della nostra economia.",
  "Proven and functioning model": "Modello comprovato e funzionante",
