  "Real opportunities from the ecosystem": "Opportunita reali dall'ecosistema",
  "Real, operational companies": "Aziende reali e operative",
  "Recognitions that demonstrate our concrete dedication to professional inclusion and social sustainability.": "Riconoscimenti che dimostrano il nostro impegno concreto per l'inclusione professionale e la sostenibilita sociale.",
  "Recurring business models": "Modelli di business ricorrenti",
