  "Risk is distributed across different companies, industries, and regions.": "Il rischio e distribuito tra diverse aziende, settori e regioni.",
  "Room to discover what you're good at and develop it over time.": "Spazio per scoprire in cosa sei bravo e svilupparlo nel tempo.",
  "Scalable expansion and partnerships": "Espansione scalabile e partnership",
  "Scalable growth": "Crescita scalabile",
  "Security + growth": "Sicurezza + crescita",
