  "Share proof": "Condividi prova",
  "Shared indicators, transparent reporting and periodic review. We show results, we don't tell stories.": "Indicatori condivisi, reporting trasparente e revisione periodica. Mostriamo risultati, non raccontiamo storie.",
  "Social inequalities": "Disuguaglianze sociali",
  "Social sustainability for us also means promoting new forms of collaboration. In an increasingly connected world, innovation and progress no longer arise in isolation but through cooperation between people, companies, and organizations.": "Per noi sostenibilita sociale significa anche promuovere nuove forme di collaborazione. In un mondo sempre piu connesso, innovazione e progresso non nascono piu in isolamento, ma dalla cooperazione tra persone, aziende e organizzazioni.",
  "Solution Providers": "Fornitori di soluzioni",
  "Solutions developed inside the ecosystem.": "Soluzioni sviluppate all'interno dell'ecosistema.",
  "Solutions that are ready for immediate use.": "Soluzioni pronte per l'uso immediato.",
  "Sponsors and partners build the training paths. You learn where the skills are really needed - not in the abstract.": "Sponsor e partner costruiscono i percorsi formativi. Impari dove le competenze sono davvero necessarie, non in astratto.",
  "Sponsors and partners of the ecosystem build the learning paths. You learn where you work.": "Sponsor e partner dell'ecosistema costruiscono i percorsi di apprendimento. Impari dove lavori.",
  "Stability even in times of global change.": "Stabilita anche in tempi di cambiamento globale.",
  "Start the conversation": "Avvia la conversazione",
  "Start with proof, add learning, then become visible to companies that need what you can actually do.": "Inizia dalla prova, aggiungi apprendimento e diventa visibile alle aziende che hanno bisogno di cio che sai davvero fare.",
  "Stiftung ToGo - Opening Eyes": "Stiftung ToGo - Opening Eyes",
  "Strategic connections for collective growth.": "Connessioni strategiche per una crescita collettiva.",
