  "Technology and Humanity": "Tecnologia e umanita",
  "technology to transform real spaces into experiential digital worlds.": "tecnologia per trasformare spazi reali in mondi digitali esperienziali.",
  "Technology, networks and resilience working as one operating system.": "Tecnologia, reti e resilienza che lavorano come un unico sistema operativo.",
