  "Territorial Rights": "Diritti territoriali",
  "The benefits of being part of an integrated and high-performance ecosystem.": "I vantaggi di far parte di un ecosistema integrato e ad alte prestazioni.",
  "The best people come to companies that offer experience verifiable in the Identity.": "Le persone migliori arrivano nelle aziende che offrono esperienze verificabili nella Identity.",
  "the ecosystem companies attest the experience you've built working with them": "le aziende dell'ecosistema attestano l'esperienza che hai costruito lavorando con loro",
  "The EI Generation was born to address the real-world challenges and turn them into sustainable opportunities.": "La EI Generation e nata per affrontare le sfide reali e trasformarle in opportunita sostenibili.",
  "The entrepreneur program is ideal for:": "Il programma entrepreneur e ideale per:",
  "The Experience Identity is different. Every experience you add is attested by whoever had you do it â€” a company in the ecosystem, an Academy partner, a real project. What people see is your actual work, not your self-promotion.": "The Esperienza Identity is different. Every experience you add is attested by whoever had you do it â€” a company in the ecosistema, an Academy partner, a real project. What persone see is your actual work, not your self-promotion.",
  "The Franchise Partner is the official EI.one representative in a territory. They manage and develop the local ecosystem, coordinating modules, partners, and clients.": "Il Franchise Partner e il rappresentante ufficiale di EI.one in un territorio. Gestisce e sviluppa l'ecosistema locale, coordinando moduli, partner e clienti.",
  "The Identity follows you from one role to the next. It grows with you, even if you change company.": "La Identity ti segue da un ruolo all'altro. Cresce con te, anche se cambi azienda.",
  "The Identity isn't an isolated page. It's where the two doors of ei.one meet.": "La Identity non e una pagina isolata. E il punto in cui si incontrano le due porte di ei.one.",
  "The License Partner uses one or more EI.one modules within their own company. They remain independent but operate according to ecosystem standards.": "Il License Partner utilizza uno o piu moduli EI.one nella propria azienda. Rimane indipendente, ma opera secondo gli standard dell'ecosistema.",
  "The White Label Partner uses EI.one technology, processes, and modules under their own brand. EI.one works \"behind the scenes\".": "Il White Label Partner utilizza tecnologia, processi e moduli EI.one con il proprio brand. EI.one lavora dietro le quinte.",
  "The workplace becomes a learning engine for the people who work in it.": "Il luogo di lavoro diventa un motore di apprendimento per le persone che vi lavorano.",
  "They are independent, but the more you use them together, the more they deliver.": "Sono indipendenti, ma piu li usi insieme, piu valore generano.",
  "This-Priis - SVA Zürich": "This-Priis - SVA Zürich",
  "Those looking for investments with real impact.": "Chi cerca investimenti con impatto reale.",
  "Three ways to participate in the EI.one ecosystem, from full local leadership to modular activation and brand-integrated infrastructure.": "Tre modi per partecipare all'ecosistema EI.one: dalla leadership locale completa all'attivazione modulare e all'infrastruttura integrata nel brand.",
  "Through projects in the fields of renewable energy and energy efficiency, we support companies in making their processes more environmentally friendly.": "Attraverso progetti nei campi delle energie rinnovabili e dell'efficienza energetica, aiutiamo le aziende a rendere i processi piu rispettosi dell'ambiente.",
  "Tools that move ideas into practical use.": "Strumenti che portano le idee all'uso pratico.",
  "Uniting Business and Values": "Unire business e valori",
  "Very High": "Molto alta",
  "Virtual Showrooms": "Showroom virtuali",
  "Visit Stiftung ToGo": "Visita Stiftung ToGo",
  "Visit SVA Zürich": "Visit SVA Zürich",
  "We analyse real opportunities, assess technical and economic feasibility and only select what delivers concrete impact.": "Analizziamo opportunita reali, valutiamo fattibilita tecnica ed economica e selezioniamo solo cio che genera impatto concreto.",
  "We are not spectators of change": "Non siamo spettatori del cambiamento",
  "We are not spectators of change.": "Non siamo spettatori del cambiamento.",
  "We are the architects of change.": "Siamo gli architetti del cambiamento.",
  "We are the designers of change. EI.one is the home of the EI Generation.": "Siamo i progettisti del cambiamento. EI.one e la casa della EI Generation.",
  "We Are the EI Generation": "Siamo la EI Generation",
  "We believe businesses have a responsibility to contribute to a better world.": "Crediamo che le aziende abbiano la responsabilita di contribuire a un mondo migliore.",
  "We build the financial model, identify partners and investors, and define success indicators before we start.": "Costruiamo il modello finanziario, identifichiamo partner e investitori e definiamo gli indicatori di successo prima di iniziare.",
  "We coordinate execution with network partners. Technical capabilities come from the ecosystem; the orchestration comes from EI.one.": "Coordiniamo l'esecuzione con i partner della rete. Le capacita tecniche arrivano dall'ecosistema; l'orchestrazione da EI.one.",
  "We don't promise shortcuts. We build the future.": "Non promettiamo scorciatoie. Costruiamo il futuro.",
  "We follow no trends. We build structures that last.": "Non seguiamo mode. Costruiamo strutture che durano.",
  "What EI.one is": "Che cos'e EI.one",
  "What you did, attested by the people who saw you do it.": "Cio che hai fatto, attestato dalle persone che ti hanno visto farlo.",
  "when you finish a learning track, the experience lands straight in your Identity": "quando completi un percorso di apprendimento, l'esperienza entra direttamente nella tua Identity",
  "Where sustainability becomes operational.": "Dove la sostenibilita diventa operativa.",
  "White Label": "White Label",
  "Work delivered, with results, duration and the role you played.": "Lavoro realizzato, con risultati, durata e ruolo svolto.",
  "You are a co-builder of the system.": "Sei co-costruttore del sistema.",
  "You are not just a partner.": "Non sei solo un partner.",
  "you build real experiences inside the ecosystem's companies while growing your own project.": "costruisci esperienze reali nelle aziende dell'ecosistema mentre fai crescere il tuo progetto.",
  "you crystallize years of work into a profile that proves itself and lets you be found.": "trasformi anni di lavoro in un profilo che si dimostra da solo e ti rende trovabile.",
  "You decide what's public, what's private and what's visible only via a shared link.": "Decidi cosa e pubblico, cosa e privato e cosa e visibile solo tramite link condiviso.",
  "you want to discover where you fit, without relying only on the first CV you send out.": "vuoi scoprire dove ti inserisci, senza dipendere solo dal primo CV che invii.",
  "Your Brand, Our Infrastructure": "Il tuo brand, la nostra infrastruttura",
  "Your digital record of what actually did. Verified by the ecosystem's companies who saw you do it.": "Il tuo registro digitale di cio che hai fatto davvero. Verificato dalle aziende dell'ecosistema che ti hanno visto farlo.",
  "Your digital record of what you actually did. Verified by the ecosystem's companies who saw you do it.": "Il tuo registro digitale di cio che hai fatto davvero. Verificato dalle aziende dell'ecosistema che ti hanno visto farlo.",
  "Your digital register, verified by the companies of the ecosystem. Build it over time, share it when you need to.": "Il tuo registro digitale, verificato dalle aziende dell'ecosistema. Costruiscilo nel tempo e condividilo quando serve.",
  "For companies &rarr;": "Per aziende &rarr;",
  "For people &rarr;": "Per persone &rarr;",
