  "The company is no longer just a workplace: it becomes a hub of value for society.": "L'azienda non e piu solo un luogo di lavoro: diventa un hub di valore per la societa.",
  "Join the companies of the ecosystem that are changing the way of doing business: together, not alone.": "Unisciti alle aziende dell'ecosistema che stanno cambiando il modo di fare business: insieme, non da soli.",
  "a Identity that tells your experiences better than any pitch.": "una Identity che racconta le tue esperienze meglio di qualsiasi pitch.",
