// Italian explicit remaining translations.
Object.assign(it, {
  "ei.one isn't built to teach people or just to connect them. It exists to transform companies into engines of learning, innovation and growth. Every company that joins the ecosystem creates new commercial relationships, attracts talent, develops skills, increases its visibility, and generates measurable ESG impact.": "ei.one non nasce per insegnare alle persone o solo per collegarle. Esiste per trasformare le aziende in motori di apprendimento, innovazione e crescita. Ogni azienda che entra nell'ecosistema crea nuove relazioni commerciali, attrae talenti, sviluppa competenze, aumenta la propria visibilita e genera impatto ESG misurabile.",
  "He gave life to the": "Ha dato vita alla",
  "Entrepreneur and ecosystem builder. For over 15 years he's been developing projects that combine sustainability, technology, human network and ethical growth.": "Imprenditore e costruttore di ecosistemi. Da oltre 15 anni sviluppa progetti che uniscono sostenibilita, tecnologia, rete umana e crescita etica.",
  "He gave life to the EI Generation as a concrete response to the challenges of our time. EI.one is the result of this journey.": "Ha dato vita alla EI Generation come risposta concreta alle sfide del nostro tempo. EI.one e il risultato di questo percorso.",
  "The EI Generation consists of entrepreneurs, professionals, innovators, and talents who believe in a new development model.": "La EI Generation e composta da imprenditori, professionisti, innovatori e talenti che credono in un nuovo modello di sviluppo.",
  "We believe the future belongs to ecosystems that can unite business and values, technology and humanity, growth and responsibility, profit and positive impact.": "Crediamo che il futuro appartenga agli ecosistemi capaci di unire business e valori, tecnologia e umanita, crescita e responsabilita, profitto e impatto positivo.",
  "ei.one was born from the concrete entrepreneurial experience of the founder and partners in the sectors that today make up the ecosystem: renewable energy, business development, digital & marketing, IT & AI, real estate. We're not theory. We're practice and structure.": "ei.one nasce dall'esperienza imprenditoriale concreta del fondatore e dei partner nei settori che oggi compongono l'ecosistema: energie rinnovabili, sviluppo business, digitale e marketing, IT e AI, immobiliare. Non siamo teoria. Siamo pratica e struttura.",
  "Three-time nominees at the This-Priis - the award founded by Matthias Widmer of SVA Z?rich in 2006 to recognize companies that promote inclusion and professional integration of people with limitations.": "Tre volte nominati al This-Priis, il premio fondato da Matthias Widmer di SVA Zurigo nel 2006 per riconoscere le aziende che promuovono inclusione e integrazione professionale di persone con limitazioni.",
  "For us it's not a trophy; it's confirmation that the way we build teams works, and it scales to the entire ecosystem.": "Per noi non e un trofeo: e la conferma che il modo in cui costruiamo i team funziona e puo scalare in tutto l'ecosistema.",
  "We support the Swiss foundation Stiftung ToGo, which organizes free cataract operations in Togo. To date, the foundation has helped over 1,000 people recover their sight.": "Sosteniamo la fondazione svizzera Stiftung ToGo, che organizza operazioni gratuite di cataratta in Togo. Finora la fondazione ha aiutato oltre 1.000 persone a recuperare la vista.",
  "It's a concrete example of what we mean by \"real value\": a measurable, verifiable action that changes individual lives.": "E un esempio concreto di cio che intendiamo per valore reale: un'azione misurabile e verificabile che cambia vite individuali.",
  "Our commitments": "I nostri impegni",
  "We believe in an ecosystem that grows together with its community. These are the companies, institutions and organizations we work with, that recognize and support our work.": "Crediamo in un ecosistema che cresce insieme alla propria comunita. Queste sono le aziende, istituzioni e organizzazioni con cui lavoriamo, che riconoscono e sostengono il nostro lavoro.",
  "Ecology meets innovation": "Ecologia e innovazione si incontrano",
  "At EI.one, environmental sustainability isn't a slogan. It's an operational line with selection criteria, execution phases and impact metrics.": "In EI.one la sostenibilita ambientale non e uno slogan. E una linea operativa con criteri di selezione, fasi di esecuzione e metriche di impatto.",
  "We work with companies in our network, industrial partners and investors who share one priority: generating economic value without compromising ecological value.": "Lavoriamo con aziende della nostra rete, partner industriali e investitori che condividono una priorita: generare valore economico senza compromettere il valore ecologico.",
  "A selection of installations delivered across Switzerland in collaboration with": "Una selezione di installazioni realizzate in Svizzera in collaborazione con",
  "a partner in our ecosystem.": "un partner del nostro ecosistema.",
  "Multi-family building": "Edificio plurifamiliare",
  "Private home": "Casa privata",
  "Single-family home": "Casa unifamiliare",
  "See all references on Techede.ch": "Vedi tutte le referenze su Techede.ch",
  "For every project we publish impact indicators: tons of CO2 avoided, kWh produced from renewable sources, percentage reduction in consumption. No stories - verifiable numbers.": "Per ogni progetto pubblichiamo indicatori di impatto: tonnellate di CO2 evitate, kWh prodotti da fonti rinnovabili, percentuale di riduzione dei consumi. Niente racconti: numeri verificabili.",
  "For every project we publish impact indicators: tons of CO2 avoided, kWh produced from renewable sources, percentage reduction in consumption.": "Per ogni progetto pubblichiamo indicatori di impatto: tonnellate di CO2 evitate, kWh prodotti da fonti rinnovabili, percentuale di riduzione dei consumi.",
  "No stories - verifiable numbers.": "Niente racconti: numeri verificabili.",
  "Cooperation model": "Modello di cooperazione",
  "In a saturated market, partnership is the key to differentiation. We offer not just a platform, but an environment of trust where businesses support each other.": "In un mercato saturo, la partnership e la chiave della differenziazione. Non offriamo solo una piattaforma, ma un ambiente di fiducia in cui le aziende si sostengono a vicenda.",
  "ei.one - The ecosystem where people build real experience and become entrepreneurs.": "ei.one - L'ecosistema in cui le persone costruiscono esperienza reale e diventano imprenditori.",
  "At ei.one, Business Units aren't \"isolated providers\". They're part of a single integrated and coordinated system. That's what makes the ecosystem really work.": "In ei.one le Business Unit non sono fornitori isolati. Sono parte di un unico sistema integrato e coordinato. E questo che fa funzionare davvero l'ecosistema.",
  "The EI.one Marketplace offers access to exclusive products and technologies born from our ecosystem. Our goal is to provide businesses with tools that make their visions tangible and real.": "Il Marketplace EI.one offre accesso a prodotti e tecnologie esclusivi nati dal nostro ecosistema. Il nostro obiettivo e fornire alle aziende strumenti che rendano le loro visioni tangibili e reali.",
  "Energy & Sustainability": "Energia e sostenibilita",
  "Sales & Business Development": "Vendite e sviluppo business",
  "Integrated Energy Systems": "Sistemi energetici integrati",
  "3D Visualization & Virtual Events": "Visualizzazione 3D ed eventi virtuali",
  "Digital & Brand Growth": "Crescita digitale e del brand",
  "IT, AI & Academy Systems": "IT, AI e sistemi Academy",
  "Professional Hygiene & Cleaning": "Igiene professionale e pulizia",
  "Referral Marketing & Business Network": "Referral marketing e rete business",
  "Real Estate & Infrastructure": "Immobiliare e infrastrutture",
  "Techede is the module dedicated to renewable energy and green solutions. We develop photovoltaic projects, energy storage systems, and consulting for energy transition. Our goal is to make clean energy accessible and profitable for businesses and individuals, supporting decarbonization and energy independence.": "Techede e il modulo dedicato alle energie rinnovabili e alle soluzioni verdi. Sviluppiamo progetti fotovoltaici, sistemi di accumulo energetico e consulenza per la transizione energetica. Il nostro obiettivo e rendere l'energia pulita accessibile e profittevole per aziende e privati, sostenendo decarbonizzazione e indipendenza energetica.",
  "SalesMaster is the module specialized in strategic sales and business development. We offer commercial training, sales team coaching, customized CRM systems, and customer acquisition strategies. We transform relationships into sustainable growth through proven methodologies focused on concrete results.": "SalesMaster e il modulo specializzato in vendite strategiche e sviluppo business. Offriamo formazione commerciale, coaching dei team di vendita, sistemi CRM personalizzati e strategie di acquisizione clienti. Trasformiamo le relazioni in crescita sostenibile con metodologie comprovate e orientate a risultati concreti.",
  "EQUICO?? is the module dedicated to integrated energy systems for businesses and properties. From feasibility analysis to the design and implementation of solar, wind and energy storage installations, we transform energy from a cost factor into a revenue source. We support high-energy-consuming companies towards full sustainable energy independence.": "EQUICO? e il modulo dedicato ai sistemi energetici integrati per aziende e immobili. Dall'analisi di fattibilita alla progettazione e realizzazione di impianti solari, eolici e di accumulo, trasformiamo l'energia da costo a fonte di ricavo. Supportiamo le aziende ad alto consumo verso una piena indipendenza energetica sostenibile.",
  "Archit.ooo is the module for 3D visualization and virtual events. We use Expi4D technology to create digital twins, immersive tours, virtual showrooms, and online exhibition spaces. We design the future by making every space accessible and interactive, revolutionizing how projects and properties are presented.": "Archit.ooo e il modulo per visualizzazione 3D ed eventi virtuali. Usiamo la tecnologia Expi4D per creare gemelli digitali, tour immersivi, showroom virtuali e spazi espositivi online. Progettiamo il futuro rendendo ogni spazio accessibile e interattivo, rivoluzionando il modo in cui progetti e immobili vengono presentati.",
  "MarketingMaster is the module for digital growth and brand positioning. We develop integrated marketing strategies, social media management, valuable content, advertising campaigns, and SEO. We build visibility with real value, transforming your online presence into concrete and measurable business opportunities.": "MarketingMaster e il modulo per crescita digitale e posizionamento del brand. Sviluppiamo strategie di marketing integrate, gestione social media, contenuti di valore, campagne pubblicitarie e SEO. Costruiamo visibilita con valore reale, trasformando la presenza online in opportunita di business concrete e misurabili.",
  "Netmaster is the technological heart of the EI.one ecosystem. We offer software development, AI solutions, cloud infrastructure, cybersecurity, and digital training through our Academy. The technological backbone that coordinates all modules, manages data, and trains the professionals of the EI Generation.": "Netmaster e il cuore tecnologico dell'ecosistema EI.one. Offriamo sviluppo software, soluzioni AI, infrastruttura cloud, cybersecurity e formazione digitale tramite la nostra Academy. E la spina dorsale tecnologica che coordina tutti i moduli, gestisce i dati e forma i professionisti della EI Generation.",
  "Cleanlife is the module specialized in professional hygiene and cleaning solutions for businesses and facilities. With over 20 years of experience in the Swiss market, we offer industrial cleaning chemicals, professional machinery, maintenance services and tailored technical consulting for hotels, offices, restaurants and healthcare facilities.": "Cleanlife e il modulo specializzato in igiene professionale e soluzioni di pulizia per aziende e strutture. Con oltre 20 anni di esperienza nel mercato svizzero, offriamo prodotti chimici per pulizia industriale, macchinari professionali, servizi di manutenzione e consulenza tecnica su misura per hotel, uffici, ristoranti e strutture sanitarie.",
  "BNI focuses primarily on economic sustainability through systematic referral marketing that generates measurable growth and revenue. Social sustainability shows in values like 'Givers Gain', long-term relationships and personal development.": "BNI si concentra principalmente sulla sostenibilita economica attraverso un referral marketing sistematico che genera crescita e ricavi misurabili. La sostenibilita sociale emerge in valori come 'Givers Gain', relazioni a lungo termine e sviluppo personale.",
  "PropertyMaster is the module dedicated to sustainable real estate and infrastructure. We offer real estate consulting, valuations, asset management, project development, and energy requalification of buildings. Future-oriented real estate: we integrate sustainability, technology, and long-term value.": "PropertyMaster e il modulo dedicato a immobiliare e infrastrutture sostenibili. Offriamo consulenza immobiliare, valutazioni, asset management, sviluppo progetti e riqualificazione energetica degli edifici. Immobiliare orientato al futuro: integriamo sostenibilita, tecnologia e valore a lungo termine.",
  "Archit.ooo is the innovative platform for 3D visualization and virtual events. We use the groundbreaking": "Archit.ooo e la piattaforma innovativa per visualizzazione 3D ed eventi virtuali. Usiamo la rivoluzionaria",
  "Whether digital twins, immersive tours, virtual showrooms, or online exhibition spaces - Archit.ooo makes spaces accessible and interactive worldwide. We revolutionize the way projects and real estate are presented and experienced.": "Che si tratti di gemelli digitali, tour immersivi, showroom virtuali o spazi espositivi online, Archit.ooo rende gli spazi accessibili e interattivi in tutto il mondo. Rivoluzioniamo il modo in cui progetti e immobili vengono presentati e vissuti.",
  "Three-time nominees at the This-Priis - the award founded by Matthias Widmer of SVA Zürich in 2006 to recognize companies that promote inclusion and professional integration of people with limitations.": "Tre volte nominati al This-Priis, il premio fondato da Matthias Widmer di SVA Zurigo nel 2006 per riconoscere le aziende che promuovono l'inclusione e l'integrazione professionale di persone con limitazioni.",
  "EQUICOÂ² is the module dedicated to integrated energy systems for businesses and properties. From feasibility analysis to the design and implementation of solar, wind and energy storage installations, we transform energy from a cost factor into a revenue source. We support high-energy-consuming companies towards full sustainable energy independence.": "EQUICO² e il modulo dedicato ai sistemi energetici integrati per aziende e immobili. Dall'analisi di fattibilita alla progettazione e realizzazione di impianti solari, eolici e di accumulo energetico, trasformiamo l'energia da costo a fonte di ricavo. Supportiamo le aziende ad alto consumo energetico verso una piena indipendenza energetica sostenibile."
})

