Object.assign(it, {
  "Every experience at an ecosystem company is attested by whoever had you do it and recorded on the blockchain as an immutable credential. Attachments, roles, results â€” all verifiable.": "Ogni esperienza in un'azienda dell'ecosistema viene attestata da chi ti ha affidato il lavoro e registrata sulla blockchain come credenziale immutabile. Allegati, ruoli e risultati: tutto verificabile.",
  "The Experience Identity is different. Every experience you add is attested by whoever had you do it â€” a company in the ecosystem, an Academy partner, a real project. What people see is your actual work, not your self-promotion.": "La Experience Identity e diversa. Ogni esperienza che aggiungi viene attestata da chi ti ha affidato il lavoro: un'azienda dell'ecosistema, un partner Academy o un progetto reale. Cio che le persone vedono e il tuo lavoro concreto, non la tua autopromozione.",
  "EQUICO² is the module dedicated to integrated energy systems for businesses and properties. From feasibility analysis to the design and implementation of solar, wind and energy storage installations, we transform energy from a cost factor into a revenue source. We support high-energy-consuming companies towards full sustainable energy independence.": "EQUICO2 e il modulo dedicato ai sistemi energetici integrati per aziende e immobili. Dall'analisi di fattibilita alla progettazione e realizzazione di impianti solari, eolici e di accumulo energetico, trasformiamo l'energia da costo a fonte di ricavo. Supportiamo le aziende ad alto consumo energetico verso una piena indipendenza energetica sostenibile.",
  "EQUICOÂ² is the module dedicated to integrated energy systems for businesses and properties. From feasibility analysis to the design and implementation of solar, wind and energy storage installations, we transform energy from a cost factor into a revenue source. We support high-energy-consuming companies towards full sustainable energy independence.": "EQUICO2 e il modulo dedicato ai sistemi energetici integrati per aziende e immobili. Dall'analisi di fattibilita alla progettazione e realizzazione di impianti solari, eolici e di accumulo energetico, trasformiamo l'energia da costo a fonte di ricavo. Supportiamo le aziende ad alto consumo energetico verso una piena indipendenza energetica sostenibile."
})

