  'The Human at the Center': 'L’humain au centre',
  'Humans are at the center of every sustainable development. For us, social sustainability means combining economic progress with responsibility towards people, communities, and future generations.': 'L’humain est au centre de tout développement durable. Pour nous, la durabilité sociale signifie unir progrès économique et responsabilité envers les personnes, les communautés et les générations futures.',
  'At EI.one, we believe that sustainable innovation can only emerge when people have access to knowledge, education, and new opportunities. That is why we promote a corporate culture based on collaboration, trust, diversity, and personal development.': 'Chez EI.one, nous pensons que l’innovation durable ne peut naître que lorsque les personnes ont accès au savoir, à la formation et à de nouvelles opportunités. C’est pourquoi nous encourageons une culture d’entreprise fondée sur la collaboration, la confiance, la diversité et le développement personnel.',
