  // About / engagements / sponsor
  'About Us': 'À propos de nous',
  "ei.one isn't built to teach people or just to connect them. It exists to transform companies into engines of learning, innovation and growth. Every company that joins the ecosystem creates new commercial relationships, attracts talent, develops skills, increases its visibility, and generates measurable ESG impact.": 'ei.one n’a pas été créé seulement pour enseigner ou connecter les personnes. Il existe pour transformer les entreprises en moteurs d’apprentissage, d’innovation et de croissance. Chaque entreprise qui rejoint l’écosystème crée de nouvelles relations commerciales, attire des talents, développe des compétences, augmente sa visibilité et génère un impact ESG mesurable.',
  'The company is no longer just a workplace: it becomes a hub of value for society.': 'L’entreprise n’est plus seulement un lieu de travail : elle devient un hub de valeur pour la société.',
