  'We believe the future belongs to ecosystems that can unite business and values, technology and humanity, growth and responsibility, profit and positive impact.': 'Nous croyons que l’avenir appartient aux écosystèmes capables d’unir business et valeurs, technologie et humanité, croissance et responsabilité, profit et impact positif.',
