  'Our Engagement': 'Notre engagement',
  'We believe in an ecosystem that grows together with its community. These are the companies, institutions and organizations we work with, that recognize and support our work.': 'Nous croyons en un écosystème qui grandit avec sa communauté. Voici les entreprises, institutions et organisations avec lesquelles nous travaillons, qui reconnaissent et soutiennent notre travail.',
  'Our Partners': 'Nos partenaires',
  'Companies, institutions and organizations that recognize and support our work.': 'Entreprises, institutions et organisations qui reconnaissent et soutiennent notre travail.',
  'Milestones': 'Jalons',
  'Our commitments': 'Nos engagements',
  'We believe businesses have a responsibility to contribute to a better world.': 'Nous croyons que les entreprises ont la responsabilité de contribuer à un monde meilleur.',
  'Support growth that can be verified.': 'Soutenir une croissance vérifiable.',
  'Sponsoring EI.one means supporting a human-centred ecosystem where companies, talents and schools turn real experience into shared value.': 'Sponsoriser EI.one, c’est soutenir un écosystème centré sur l’humain où entreprises, talents et écoles transforment l’expérience réelle en valeur partagée.',
  'Become a Sponsor': 'Devenir sponsor',
