  'Visible impact': 'Impact visible',
  'Our sponsors': 'Nos sponsors',
  'Companies supporting the EI.one ecosystem.': 'Entreprises qui soutiennent l’écosystème EI.one.',
  'We are grateful to our sponsors for their trust, collaboration, and commitment to supporting innovation, education, and meaningful connections. Their contribution plays an essential role in helping us build a stronger, human-centered ecosystem.': 'Nous remercions nos sponsors pour leur confiance, leur collaboration et leur engagement à soutenir l’innovation, la formation et les connexions significatives. Leur contribution joue un rôle essentiel pour nous aider à construire un écosystème plus fort et centré sur l’humain.',

