  '3D Technology': 'Technologie 3D',
  '3D Visualization & Virtual Events': 'Visualisation 3D & événements virtuels',
  'A CV says whatever you want it to. It also says very little of substance: job titles, years, keywords. In the age of the AI transition, that\'s not enough for anyone â€” not for job seekers, not for employers.': 'Un CV dit ce que vous voulez montrer. Mais il dit aussi très peu de choses essentielles : titres, années, mots-clés. À l’ère de la transition IA, cela ne suffit plus à personne : ni aux candidats, ni aux employeurs.',
  'A clear path from opportunity to proof.': 'Un chemin clair de l’opportunité à la preuve.',
  'A clearer investment frame: tangible structures, defined roles, and impact logic that can scale over time.': 'Un cadre d’investissement plus clair : des structures tangibles, des rôles définis et une logique d’impact capable de grandir dans le temps.',
  'A client enters through one module and benefits from the entire ecosystem.': 'Un client entre par un module et bénéficie de tout l’écosystème.',
  'A long-term growth logic focusing on sustainability': 'Une logique de croissance à long terme axée sur la durabilité',
  'A model where:': 'Un modèle dans lequel :',
  'A new entrepreneurial culture': 'Une nouvelle culture entrepreneuriale',
  'A selection of installations delivered across Switzerland in collaboration with': 'Une sélection d’installations réalisées en Suisse en collaboration avec',
  'A system of specialised Business Units â€” energy, sales, marketing, IT & AI, real estate, 3D â€” working together. Enter through one, benefit from all.': 'Un système de Business Units spécialisées — énergie, vente, marketing, IT & IA, immobilier, 3D — qui travaillent ensemble. Entrez par l’une, bénéficiez de toutes.',
  'A system of specialised Business Units — energy, sales, marketing, IT & AI, real estate, 3D — working together. Enter through one, benefit from all.': 'Un système de Business Units spécialisées — énergie, vente, marketing, IT & IA, immobilier, 3D — qui travaillent ensemble. Entrez par l’une, bénéficiez de toutes.',
  'A unique digital profile with a shareable link. It\'s yours, it follows you across your whole working life, no matter where you work.': 'Un profil numérique unique avec un lien partageable. Il vous appartient et vous accompagne toute votre vie professionnelle, où que vous travailliez.',
  'AI is rewriting roles faster than CVs can keep up. Résumés say less and less about what a person can actually do, and companies struggle more and more to find the right skills.': 'L’IA réécrit les rôles plus vite que les CV ne peuvent suivre. Les CV disent de moins en moins ce qu’une personne sait réellement faire, et les entreprises ont de plus en plus de mal à trouver les bonnes compétences.',
