  'Archit.ooo is the innovative platform for 3D visualization and virtual events. We use the groundbreaking': 'Archit.ooo est la plateforme innovante pour la visualisation 3D et les événements virtuels. Nous utilisons la technologie révolutionnaire',
  'Archit.ooo is the module for 3D visualization and virtual events. We use Expi4D technology to create digital twins, immersive tours, virtual showrooms, and online exhibition spaces. We design the future by making every space accessible and interactive, revolutionizing how projects and properties are presented.': 'Archit.ooo est le module dédié à la visualisation 3D et aux événements virtuels. Nous utilisons la technologie Expi4D pour créer des jumeaux numériques, des visites immersives, des showrooms virtuels et des espaces d’exposition en ligne. Nous concevons l’avenir en rendant chaque espace accessible et interactif.',
  'Areas of action': 'Domaines d’action',
  'As the EI Generation, we commit every day to a better future.': 'En tant que EI Generation, nous nous engageons chaque jour pour un avenir meilleur.',
  'Aspiring entrepreneurs': 'Entrepreneurs en devenir',
  'At EI.one - Ecosystem Intelligence, we develop an intelligent ecosystem that connects companies, technologies, talents, and investors. Our goal is to support organizations in creating sustainable value, opening new markets, and strengthening their competitiveness in the long term.': 'Chez EI.one - Ecosystem Intelligence, nous développons un écosystème intelligent qui relie entreprises, technologies, talents et investisseurs. Notre objectif est d’aider les organisations à créer une valeur durable, à ouvrir de nouveaux marchés et à renforcer leur compétitivité à long terme.',
  'At EI.one, environmental sustainability isn\'t a slogan. It\'s an operational line with selection criteria, execution phases and impact metrics.': 'Chez EI.one, la durabilité environnementale n’est pas un slogan. C’est une ligne opérationnelle avec des critères de sélection, des phases d’exécution et des indicateurs d’impact.',
  'At EI.one, we believe in concrete values that guide every partnership. We are not looking for simple affiliates. We are looking for ecosystem leaders.': 'Chez EI.one, nous croyons en des valeurs concrètes qui guident chaque partenariat. Nous ne cherchons pas de simples affiliés. Nous cherchons des leaders d’écosystème.',
  'At EI.one, we combine technological innovation with ecological awareness. Our approach is based on the conviction that sustainable solutions are not only necessary but also offer enormous opportunities for the economy, society, and innovation.': 'Chez EI.one, nous associons innovation technologique et conscience écologique. Notre approche repose sur la conviction que les solutions durables sont nécessaires et offrent aussi de grandes opportunités pour l’économie, la société et l’innovation.',
  'Award Received': 'Prix reçu',
  'BNI focuses primarily on economic sustainability through systematic referral marketing that generates measurable growth and revenue. Social sustainability shows in values like \'Givers Gain\', long-term relationships and personal development.': 'BNI se concentre principalement sur la durabilité économique grâce à un marketing de recommandation systématique qui génère une croissance et des revenus mesurables. La durabilité sociale se reflète dans des valeurs comme « Givers Gain », les relations à long terme et le développement personnel.',
