  'By combining digitalization, platform economy, artificial intelligence, and strategic networks, we enable more efficient work and faster innovation.': 'En combinant digitalisation, économie de plateforme, intelligence artificielle et réseaux stratégiques, nous permettons un travail plus efficace et une innovation plus rapide.',
  'By joining the EI Generation, you gain access to an already structured, tested, and sustainable growth-oriented ecosystem.': 'En rejoignant la EI Generation, vous accédez à un écosystème déjà structuré, testé et orienté vers une croissance durable.',
