  'EI Generation': 'EI Generation',
  'EI.ONE creates an environment where capital is used efficiently, growth is controlled and scaled, and risks are structurally reduced.': 'EI.ONE crée un environnement où le capital est utilisé efficacement, la croissance est contrôlée et mise à l’échelle, et les risques sont structurellement réduits.',
  'EI.ONE thrives on complementary entrepreneurs.': 'EI.ONE vit grâce à des entrepreneurs complémentaires.',
  'EI.one - More Than a Platform': 'EI.one - Plus qu’une plateforme',
  'EI.one Brand': 'Marque EI.one',
  'EI.one is not a single company idea. It is a functioning scalable system built around education, experience, economy, and environment.': 'EI.one n’est pas une simple idée d’entreprise. C’est un système fonctionnel et évolutif construit autour de la formation, de l’expérience, de l’économie et de l’environnement.',
  'EI.one is not just a project. It is much more.': 'EI.one n’est pas seulement un projet. C’est beaucoup plus.',
  'EI.one is the home of the EI Generation.': 'EI.one est la maison de la EI Generation.',
  'EI.one stands for a new generation of economic systems - intelligent, connected, and sustainable.': 'EI.one représente une nouvelle génération de systèmes économiques : intelligents, connectés et durables.',
  'EI.one supports this development through a globally oriented network that brings together talents, ideas, and projects. Our goal is to promote an economy that is human, inclusive, and future-oriented.': 'EI.one soutient ce développement grâce à un réseau orienté à l’international qui réunit talents, idées et projets. Notre objectif est de promouvoir une économie humaine, inclusive et tournée vers l’avenir.',
  'EQUICO?? is the module dedicated to integrated energy systems for businesses and properties. From feasibility analysis to the design and implementation of solar, wind and energy storage installations, we transform energy from a cost factor into a revenue source. We support high-energy-consuming companies towards full sustainable energy independence.': 'EQUICO² est le module dédié aux systèmes énergétiques intégrés pour entreprises et biens immobiliers. De l’analyse de faisabilité à la conception et à la mise en œuvre d’installations solaires, éoliennes et de stockage, nous transformons l’énergie d’un facteur de coût en source de revenus. Nous accompagnons les entreprises à forte consommation vers une indépendance énergétique durable.',
  'EQUICO² is the module dedicated to integrated energy systems for businesses and properties. From feasibility analysis to the design and implementation of solar, wind and energy storage installations, we transform energy from a cost factor into a revenue source. We support high-energy-consuming companies towards full sustainable energy independence.': 'EQUICO² est le module dédié aux systèmes énergétiques intégrés pour entreprises et biens immobiliers. De l’analyse de faisabilité à la conception et à la mise en œuvre d’installations solaires, éoliennes et de stockage, nous transformons l’énergie d’un facteur de coût en source de revenus. Nous accompagnons les entreprises à forte consommation vers une indépendance énergétique durable.',
  'EQUICOÂ² is the module dedicated to integrated energy systems for businesses and properties. From feasibility analysis to the design and implementation of solar, wind and energy storage installations, we transform energy from a cost factor into a revenue source. We support high-energy-consuming companies towards full sustainable energy independence.': 'EQUICO² est le module dédié aux systèmes énergétiques intégrés pour entreprises et biens immobiliers. De l’analyse de faisabilité à la conception et à la mise en œuvre d’installations solaires, éoliennes et de stockage, nous transformons l’énergie d’un facteur de coût en source de revenus. Nous accompagnons les entreprises à forte consommation vers une indépendance énergétique durable.',
