  'ESG at the heart of everything': 'L’ESG au cœur de tout',
  'Each unit has its own focus, but they are designed to work together as one coordinated growth system.': 'Chaque unité a son propre focus, mais elles sont conçues pour fonctionner ensemble comme un système de croissance coordonné.',
  'Economic crises': 'Crises économiques',
  'Economic growth built on synergy, not internal competition.': 'Croissance économique fondée sur la synergie, pas sur la concurrence interne.',
  'Economic sustainability for us means creating systems that remain stable even in times of uncertainty and global change. Companies should not only grow but continuously evolve and become resilient to change.': 'Pour nous, la durabilité économique signifie créer des systèmes qui restent stables même en période d’incertitude et de changement mondial. Les entreprises ne doivent pas seulement croître, mais évoluer en continu et devenir résilientes.',
