  'For every project we publish impact indicators: tons of CO2 avoided, kWh produced from renewable sources, percentage reduction in consumption. No stories - verifiable numbers.': 'Pour chaque projet, nous publions des indicateurs d’impact : tonnes de CO2 évitées, kWh produits à partir de sources renouvelables, pourcentage de réduction de la consommation. Pas de récits : des chiffres vérifiables.',
