  'Internships, project work and mentoring become a channel of verified talent, trusted partnerships and a qualified commercial network. Your experiences attract the best. The best grow your business.': 'Les stages, le travail de projet et le mentoring deviennent un canal de talents vérifiés, de partenariats fiables et de réseau commercial qualifié. Vos expériences attirent les meilleurs. Les meilleurs font grandir votre entreprise.',
  'Invest in an ecosystem where real companies, verified talents and sustainable growth reinforce each other.': 'Investissez dans un écosystème où des entreprises réelles, des talents vérifiés et une croissance durable se renforcent mutuellement.',
  'Investing in an Ecosystem': 'Investir dans un écosystème',
  'Investors invest not only in visions, but in a robust and resilient system offering security and growth.': 'Les investisseurs n’investissent pas seulement dans des visions, mais dans un système robuste et résilient qui offre sécurité et croissance.',
  'It\'s a concrete example of what we mean by "real value": a measurable, verifiable action that changes individual lives.': 'C’est un exemple concret de ce que nous appelons la « valeur réelle » : une action mesurable et vérifiable qui change des vies individuelles.',
  'Join the EI Generation': 'Rejoindre la EI Generation',
  'Join the companies of the ecosystem that are changing the way of doing business: together, not alone.': 'Rejoignez les entreprises de l’écosystème qui changent la manière de faire des affaires : ensemble, pas seules.',
