  'Learn through the Academy, accumulate verified experience inside the ecosystem\'s companies, get found when a company actually needs what you can do.': 'Apprenez grâce à l’Academy, accumulez de l’expérience vérifiée dans les entreprises de l’écosystème et soyez trouvé lorsqu’une entreprise a réellement besoin de vos compétences.',
