  'Marketing': 'Marketing',
  'MarketingMaster is the module for digital growth and brand positioning. We develop integrated marketing strategies, social media management, valuable content, advertising campaigns, and SEO. We build visibility with real value, transforming your online presence into concrete and measurable business opportunities.': 'MarketingMaster est le module dédié à la croissance digitale et au positionnement de marque. Nous développons des stratégies marketing intégrées, la gestion des réseaux sociaux, du contenu de valeur, des campagnes publicitaires et du SEO. Nous construisons une visibilité à valeur réelle, transformant votre présence en ligne en opportunités commerciales concrètes et mesurables.',
  'Marketplace tools are selected for one reason: they have to become useful quickly, keep quality high, and create measurable business value.': 'Les outils du Marketplace sont sélectionnés pour une raison : ils doivent devenir utiles rapidement, maintenir une qualité élevée et créer une valeur business mesurable.',
