  'Projects that turn waste into resources. Reducing waste, reusing materials, building sustainable industrial processes.': 'Des projets qui transforment les déchets en ressources. Réduire les déchets, réutiliser les matériaux, construire des processus industriels durables.',
  'PropertyMaster is the module dedicated to sustainable real estate and infrastructure. We offer real estate consulting, valuations, asset management, project development, and energy requalification of buildings. Future-oriented real estate: we integrate sustainability, technology, and long-term value.': 'PropertyMaster est le module dédié à l’immobilier et aux infrastructures durables. Nous proposons conseil immobilier, évaluations, asset management, développement de projets et requalification énergétique des bâtiments. Un immobilier tourné vers l’avenir : nous intégrons durabilité, technologie et valeur à long terme.',
  'Protect the environment': 'Protéger l’environnement',
  'Protecting our environment is one of the central challenges of the 21st century. For us, ecological sustainability means using natural resources responsibly, using energy efficiently, and developing technologies that reduce the ecological footprint of our economy.': 'Protéger notre environnement est l’un des défis centraux du XXIe siècle. Pour nous, la durabilité écologique signifie utiliser les ressources naturelles de manière responsable, utiliser l’énergie efficacement et développer des technologies qui réduisent l’empreinte écologique de notre économie.',
