  'Put real, verified experience at the centre â€” not keywords. Every entry in the Identity is attested by the company that gave you the work. It\'s a fairer, more honest way to show what you\'re worth.': 'Mettez l’expérience réelle et vérifiée au centre — pas les mots-clés. Chaque entrée dans l’Identity est attestée par l’entreprise qui vous a confié le travail. C’est une manière plus juste et plus honnête de montrer votre valeur.',
