  'Social inequalities': 'Inégalités sociales',
  'Social sustainability for us also means promoting new forms of collaboration. In an increasingly connected world, innovation and progress no longer arise in isolation but through cooperation between people, companies, and organizations.': 'Pour nous, la durabilité sociale signifie aussi promouvoir de nouvelles formes de collaboration. Dans un monde de plus en plus connecté, l’innovation et le progrès ne naissent plus isolément, mais grâce à la coopération entre personnes, entreprises et organisations.',
