  'Tangible Visions': 'Visions tangibles',
  'Techede is the module dedicated to renewable energy and green solutions. We develop photovoltaic projects, energy storage systems, and consulting for energy transition. Our goal is to make clean energy accessible and profitable for businesses and individuals, supporting decarbonization and energy independence.': 'Techede est le module dédié aux énergies renouvelables et aux solutions vertes. Nous développons des projets photovoltaïques, des systèmes de stockage d’énergie et du conseil pour la transition énergétique. Notre objectif est de rendre l’énergie propre accessible et rentable pour les entreprises et les particuliers, en soutenant la décarbonation et l’indépendance énergétique.',
