  'The Business Units in the network': 'Les Business Units du réseau',
  'The EI Generation consists of entrepreneurs, professionals, innovators, and talents who believe in a new development model.': 'La EI Generation est composée d’entrepreneurs, de professionnels, d’innovateurs et de talents qui croient en un nouveau modèle de développement.',
  'The EI Generation was born to address the real-world challenges and turn them into sustainable opportunities.': 'La EI Generation est née pour répondre aux défis du monde réel et les transformer en opportunités durables.',
  'The Experience Identity is different. Every experience you add is attested by whoever had you do it Ã¢â‚¬â€ a company in the ecosystem, an Academy partner, a real project. What people see is your actual work, not your self-promotion.': 'L’Experience Identity est différente. Chaque expérience ajoutée est attestée par celui qui vous l’a confiée : une entreprise de l’écosystème, un partenaire Academy ou un projet réel. Ce que les personnes voient, c’est votre travail concret, pas votre autopromotion.',
  'The Franchise Partner is the official EI.one representative in a territory. They manage and develop the local ecosystem, coordinating modules, partners, and clients.': 'Le partenaire franchise est le représentant officiel EI.one sur un territoire. Il gère et développe l’écosystème local en coordonnant modules, partenaires et clients.',
  'The Identity follows you from one role to the next. It grows with you, even if you change company.': 'L’Identity vous suit d’un rôle à l’autre. Elle grandit avec vous, même si vous changez d’entreprise.',
  'The License Partner uses one or more EI.one modules within their own company. They remain independent but operate according to ecosystem standards.': 'Le partenaire licence utilise un ou plusieurs modules EI.one dans sa propre entreprise. Il reste indépendant, mais travaille selon les standards de l’écosystème.',
  'The White Label Partner uses EI.one technology, processes, and modules under their own brand. EI.one works "behind the scenes".': 'Le partenaire White Label utilise la technologie, les processus et les modules EI.one sous sa propre marque. EI.one travaille en coulisses.',
  'The benefits of being part of an integrated and high-performance ecosystem.': 'Les avantages de faire partie d’un écosystème intégré et performant.',
  'The best people come to companies that offer experience verifiable in the Identity.': 'Les meilleurs talents viennent dans les entreprises qui offrent une expérience vérifiable dans l’Identity.',
  'The company is no longer just a workplace. It becomes a hub of value for society.': 'L’entreprise n’est plus seulement un lieu de travail. Elle devient un hub de valeur pour la société.',
  'The entrepreneur program is ideal for:': 'Le programme entrepreneur est idéal pour :',
