  'Those looking for investments with real impact.': 'Ceux qui recherchent des investissements à impact réel.',
  'Those who want to change': 'Ceux qui veulent changer',
  'Three modules Ã¢â‚¬â€ one to build skills, one to attest them, one to make them findable. Together they make the company a growth engine for the people who work there.': 'Trois modules : un pour construire les compétences, un pour les attester, un pour les rendre visibles. Ensemble, ils font de l’entreprise un moteur de croissance pour les personnes qui y travaillent.',
  'Three modules â€” one to build skills, one to attest them, one to make them findable. Together they make the company a growth engine for the people who work there.': 'Trois modules : un pour construire les compétences, un pour les attester, un pour les rendre visibles. Ensemble, ils font de l’entreprise un moteur de croissance pour les personnes qui y travaillent.',
  'Three steps to build a Identity that actually shows what you can do.': 'Trois étapes pour construire une Identity qui montre réellement ce que vous savez faire.',
  'Three ways to participate in the EI.one ecosystem, from full local leadership to modular activation and brand-integrated infrastructure.': 'Trois manières de participer à l’écosystème EI.one : du leadership local complet à l’activation modulaire et à l’infrastructure intégrée à la marque.',
  'Three-time nominees at the This-Priis - the award founded by Matthias Widmer of SVA Z?rich in 2006 to recognize companies that promote inclusion and professional integration of people with limitations.': 'Nommés trois fois au This-Priis, le prix fondé par Matthias Widmer de SVA Zürich en 2006 pour reconnaître les entreprises qui promeuvent l’inclusion et l’intégration professionnelle de personnes avec limitations.',
  'Three-time nominees at the This-Priis - the award founded by Matthias Widmer of SVA ZÃ¼rich in 2006 to recognize companies that promote inclusion and professional integration of people with limitations.': 'Nommés trois fois au This-Priis, le prix fondé par Matthias Widmer de SVA Zürich en 2006 pour reconnaître les entreprises qui promeuvent l’inclusion et l’intégration professionnelle de personnes avec limitations.',
  'Through projects in the fields of renewable energy and energy efficiency, we support companies in making their processes more environmentally friendly.': 'Grâce à des projets dans les domaines des énergies renouvelables et de l’efficacité énergétique, nous aidons les entreprises à rendre leurs processus plus respectueux de l’environnement.',
  'Tools that move ideas into practical use.': 'Des outils qui transforment les idées en usage pratique.',
  'Transform your students into talent recognised by the territory. Data-driven guidance, sponsored programs, direct bridge with companies. Your students\' experiences become your prestige.': 'Transformez vos étudiants en talents reconnus par le territoire. Orientation fondée sur les données, programmes sponsorisés, passerelle directe avec les entreprises. Les expériences de vos étudiants deviennent votre prestige.',
  'Transform your students into talent recognised by the territory. Data-driven guidance, sponsored programs, direct bridge with companies. Your students\\\' experiences become your prestige.': 'Transformez vos étudiants en talents reconnus par le territoire. Orientation fondée sur les données, programmes sponsorisés, passerelle directe avec les entreprises. Les expériences de vos étudiants deviennent votre prestige.',
