  'Visit Stiftung ToGo': 'Visiter Stiftung ToGo',
  'We analyse real opportunities, assess technical and economic feasibility and only select what delivers concrete impact.': 'Nous analysons de vraies opportunités, évaluons la faisabilité technique et économique et ne sélectionnons que ce qui produit un impact concret.',
  'We are not spectators of change': 'Nous ne sommes pas spectateurs du changement',
  'We are not spectators of change.': 'Nous ne sommes pas spectateurs du changement.',
  'We are the architects of change.': 'Nous sommes les architectes du changement.',
  'We are the designers of change. EI.one is the home of the EI Generation.': 'Nous sommes les concepteurs du changement. EI.one est la maison de la EI Generation.',
  'We build the financial model, identify partners and investors, and define success indicators before we start.': 'Nous construisons le modèle financier, identifions partenaires et investisseurs, et définissons les indicateurs de succès avant de commencer.',
  'We coordinate execution with network partners. Technical capabilities come from the ecosystem; the orchestration comes from EI.one.': 'Nous coordonnons l’exécution avec les partenaires du réseau. Les capacités techniques viennent de l’écosystème ; l’orchestration vient de EI.one.',
  'We follow no trends. We build structures that last.': 'Nous ne suivons pas les tendances. Nous construisons des structures qui durent.',
  'We support the Swiss foundation Stiftung ToGo, which organizes free cataract operations in Togo. To date, the foundation has helped over 1,000 people recover their sight.': 'Nous soutenons la fondation suisse Stiftung ToGo, qui organise des opérations gratuites de la cataracte au Togo. À ce jour, la fondation a aidé plus de 1 000 personnes à retrouver la vue.',
  'We work with companies in our network, industrial partners and investors who share one priority: generating economic value without compromising ecological value.': 'Nous travaillons avec des entreprises de notre réseau, des partenaires industriels et des investisseurs qui partagent une priorité : générer de la valeur économique sans compromettre la valeur écologique.',
